      "path": "src/client/status-label-policy.ts",
      "content": "/**\n * Running-turn status text policy. It owns the live status label shown next to\n * the running clock and writes changes back to the durable status-label\n * settings; ui-conversation's chat view consumes the value through the\n * optional `conversationStatus` service this plugin provides.\n */\nimport {\n  createSnapshotStore, type SettingsScope, type SnapshotStore,\n} from '@deepseek-ai/dsh-client-runtime/client'\nimport { DEFAULT_STATUS_LABEL, STATUS_LABEL_FIELD } from '../status-settings.ts'\nimport type { StatusLabelSettings } from '../status-settings.ts'\n\nexport { DEFAULT_STATUS_LABEL } from '../status-settings.ts'\n\n/**\n * Status-label policy used by both the settings row and the provided\n * conversationStatus service. The live value publishes before the durable\n * write starts, so the next turn renders the accepted text immediately.\n */\nexport class StatusLabelPolicy {\n  /** Reactive status text source for the Settings row and the service. */\n  readonly statusLabel: SnapshotStore<string> = createSnapshotStore(DEFAULT_STATUS_LABEL)\n  private readonly host: SettingsScope<StatusLabelSettings> | undefined\n\n  /**\n   * @param host - durable settings scope owned by the providing plugin;\n   * absent compositions stay process-local. The adoption subscription shares\n   * the scope's plugin lifetime — a disposed scope never publishes again, so\n   * the policy needs no release hook.\n   */\n  constructor(host?: SettingsScope<StatusLabelSettings>) {\n    this.host = host\n    if (host !== undefined) {\n      host.subscribe(() => { this.adopt(host) })\n      this.adopt(host)\n    }\n  }\n\n  /**\n   * Change the running-turn status text; the live value publishes before the\n   * durable write starts.\n   * @param text - the next status label.\n   */\n  setStatusLabel(text: string): void {\n    if (this.statusLabel.getSnapshot() === text) return\n    this.statusLabel.set(text)\n    void this.host?.set(STATUS_LABEL_FIELD, text)\n  }\n\n  /**\n   * Resolve the label actually shown: an empty stored value (the user cleared\n   * the field) falls back to the default, so a blank input never renders an\n   * empty status line.\n   * @returns the effective status text.\n   */\n  getDisplayLabel(): string {\n    return this.statusLabel.getSnapshot() || DEFAULT_STATUS_LABEL\n  }\n\n  /**\n   * Adopt the scope's accepted durable text without writing it back.\n   * @param host - the constructor-narrowed scope driving this adoption.\n   */\n  private adopt(host: SettingsScope<StatusLabelSettings>): void {\n    const section = host.getSnapshot().value\n    if (section === undefined || this.statusLabel.getSnapshot() === section.statusLabel) return\n    this.statusLabel.set(section.statusLabel)\n  }\n}\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * Status-label plugin, node half. Registers the durable `ui-status-label`\n * settings namespace when a settings provider exists; the browser half ships\n * via exports[\"./client\"], discovered through the package.json dsh.client\n * declaration.\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { settingsNamespace } from '@deepseek-ai/dsh-settings'\nimport { StatusLabelSettingsSchema } from './schema.ts'\nimport { STATUS_NAMESPACE } from './status-settings.ts'\n\nexport {\n  DEFAULT_STATUS_LABEL, STATUS_LABEL_FIELD, STATUS_NAMESPACE,\n  type StatusLabelSettings,\n} from './status-settings.ts'\n\n/**\n * Register the durable status-label section when a settings provider exists.\n * @param ctx - Host context whose optional settings service owns the section.\n */\nexport function apply(ctx: Context): void {\n  ctx.inject(['settings'], (settingsCtx) => {\n    settingsCtx.settings.register(\n      settingsNamespace(STATUS_NAMESPACE),\n      StatusLabelSettingsSchema,\n    )\n  })\n}\n"
    },
    {
      "path": "src/schema.ts",
      "content": "/** Durable status-label schema; node-half only, so the browser bundle never depends on schemastery. */\n\nimport z from '@deepseek-ai/schemastery'\nimport { DEFAULT_STATUS_LABEL, STATUS_LABEL_FIELD, type StatusLabelSettings } from './status-settings.ts'\n\n/** Durable status-label schema; also the wire envelope the browser scope validates against. */\nexport const StatusLabelSettingsSchema: z<StatusLabelSettings> = z.object({\n  [STATUS_LABEL_FIELD]: z.string().default(DEFAULT_STATUS_LABEL),\n})\n"
    },
    {
      "path": "src/status-settings.ts",
      "content": "/** Running-turn status preference: constants and the section type shared by the node and browser halves. */\n\n/** Settings namespace owned by this plugin. */\nexport const STATUS_NAMESPACE = 'ui-status-label'\n\n/** Field carrying the running-turn status text shown in the chat view. */\nexport const STATUS_LABEL_FIELD = 'statusLabel'\n\n/**\n * Default status text. Mirrors the ui-conversation extension-point default\n * (`DEFAULT_STATUS_LABEL`) so composing this provider in or out leaves the\n * chat-view label unchanged; keep both in sync.\n */\nexport const DEFAULT_STATUS_LABEL = '小难梁在0721'\n\n/** Durable status-label section shared by the Host schema and the browser scope. */\nexport interface StatusLabelSettings {\n  /** Status text shown while a turn is running. */\n  statusLabel: string\n}\n"
    }
